    @Deprecated
    public static void initialize(Configuration config) throws IllegalConfigurationException {
        initializeWithoutPlugins(config);
    }

    private static void initializeWithoutPlugins(Configuration config)
            throws IllegalConfigurationException {
        initialize(config, null);
    }

    /**
     * Returns a list of registered {@link FileSystemFactory FS factories}.
     *
     * @return a snapshot of the currently registered file system factories
     */
    @Internal
    public static List<FileSystemFactory> getRegisteredFileSystemFactories() {
        LOCK.lock();
        try {
            return new ArrayList<>(FS_FACTORIES.values());
        } finally {
            LOCK.unlock();
        }
    }

    /**
     * Hands a runtime-owned, process-level {@link MetricGroup} to every registered {@link
     * FileSystemFactory} that opts into metrics via {@link MetricsAware}.
     *
     * <p>This is the second phase of file system initialization. {@link #initialize(Configuration,
     * PluginManager)} runs at process startup, before the {@code MetricRegistry} exists; this
     * method is therefore invoked separately, once the registry and a process-level {@link
     * MetricGroup} are available. It is called from the TaskManager and JobManager entrypoints
     * only. Contexts without a process-level {@link MetricGroup} (CLI, HistoryServer, YARN client)
     * simply never call it, and their file system plugins continue to operate without emitting
     * metrics.
     *
     * <p>The call is idempotent: factories receive a child group {@code <process>.filesystem}, and
     * {@link MetricGroup#addGroup} returns the same child on repeated calls with the same parent,
     * so re-invocation does not register duplicate metrics. Factories that do not implement {@link
     * MetricsAware} are skipped.
     *
     * @param processMetricGroup the process-level metric group to register file system metrics
     *     under.
     */
    @Internal
    public static void attachMetrics(MetricGroup processMetricGroup) {
        checkNotNull(processMetricGroup, "processMetricGroup");
        LOCK.lock();
        try {
            final MetricGroup fsGroup = processMetricGroup.addGroup("filesystem");
            for (FileSystemFactory factory : FS_FACTORIES.values()) {
                // Plugin-loaded factories are wrapped in a PluginFileSystemFactory, which is itself
                // MetricsAware and forwards setMetricGroup to the inner factory under the plugin
                // classloader, so this plain instanceof reaches both wrapped and direct factories.
                if (factory instanceof MetricsAware) {
                    ((MetricsAware) factory).setMetricGroup(fsGroup);
                }
            }
        } finally {
            LOCK.unlock();
        }
    }

    /**
     * Initializes the shared file system settings.
     *
     * <p>The given configuration is passed to each file system factory to initialize the respective
     * file systems. Because the configuration of file systems may be different subsequent to the
     * call of this method, this method clears the file system instance cache.
     *
     * <p>This method also reads the default file system URI from the configuration key {@link
     * CoreOptions#DEFAULT_FILESYSTEM_SCHEME}. All calls to {@link FileSystem#get(URI)} where the
     * URI has no scheme will be interpreted as relative to that URI. As an example, assume the
     * default file system URI is set to {@code 'hdfs://localhost:9000/'}. A file path of {@code
     * '/user/USERNAME/in.txt'} is interpreted as {@code
     * 'hdfs://localhost:9000/user/USERNAME/in.txt'}.
     *
     * @param config the configuration from where to fetch the parameter.
     * @param pluginManager optional plugin manager that is used to initialized filesystems provided
     *     as plugins.
     */
    public static void initialize(Configuration config, @Nullable PluginManager pluginManager)
            throws IllegalConfigurationException {

        LOCK.lock();
        try {
            // make sure file systems are re-instantiated after re-configuration
            CACHE.clear();
            FS_FACTORIES.clear();

            Collection<Supplier<Iterator<FileSystemFactory>>> factorySuppliers = new ArrayList<>(2);
            factorySuppliers.add(() -> ServiceLoader.load(FileSystemFactory.class).iterator());

            if (pluginManager != null) {
                factorySuppliers.add(
                        () ->
                                Iterators.transform(
                                        pluginManager.load(FileSystemFactory.class),
                                        PluginFileSystemFactory::of));
            }

            final List<FileSystemFactory> fileSystemFactories =
                    loadFileSystemFactories(factorySuppliers);

            // Track registered priorities for factory selection
            final Map<String, Integer> registeredPriorities = new HashMap<>();

            // configure all file system factories
            for (FileSystemFactory factory : fileSystemFactories) {
                factory.configure(config);
                final String scheme = factory.getScheme();

                FileSystemFactory fsf =
                        ConnectionLimitingFactory.decorateIfLimited(factory, scheme, config);

                final String className = resolveFactoryClassName(factory);
                final int registeredPriority =
                        registeredPriorities.getOrDefault(scheme, Integer.MIN_VALUE);
                final int newPriority =
                        config.getOptional(CoreOptions.fileSystemFactoryPriority(scheme, className))
                                .orElse(factory.getPriority());

                LOG.info(
                        "{} filesystem factory {} for scheme '{}' "
                                + "with priority {} (highest registered priority: {})",
                        newPriority >= registeredPriority ? "Registering" : "Skipping",
                        className,
                        scheme,
                        newPriority,
                        registeredPriority);
                if (newPriority >= registeredPriority) {
                    FS_FACTORIES.put(scheme, fsf);
                    registeredPriorities.put(scheme, newPriority);
                    if (newPriority == registeredPriority) {
                        LOG.warn(
                                "Filesystem factory {} overrides a previously registered factory "
                                        + "for scheme '{}' at the same priority {}. "
                                        + "The winner depends on classloading order. "
                                        + "Set fs.{}.priority.<factoryClassName> to assign "
                                        + "explicit priorities.",
                                className,
                                scheme,
                                newPriority,
                                scheme);
                    }
                }
            }

            // configure the default (fallback) factory
            FALLBACK_FACTORY.configure(config);

            // also read the default file system scheme
            final String stringifiedUri = config.get(CoreOptions.DEFAULT_FILESYSTEM_SCHEME, null);
            if (stringifiedUri == null) {
                defaultScheme = null;
            } else {
