        for (ExecutionVertex vertex : Arrays.asList(vertex1, vertex2)) {
            ExecutionAttemptID attemptId = vertex.getCurrentExecutionAttempt().getAttemptId();
            assertThat(gateway.getOnlyTriggeredCheckpoint(attemptId).checkpointId)
