                new AcknowledgeCheckpoint(graph.getJobID(), attemptID, 3),
                TASK_MANAGER_LOCATION_INFO);
        checkpoint.get();

        Assertions.assertThat(
                        gateway.getOnlyTriggeredCheckpoint(attemptID)
