public DriverStrategy getDriverStrategy() {
        final int ls = this.config.get(getIntConfigOption(DRIVER_STRATEGY), -1);
        if (ls == -1) {
            return DriverStrategy.NONE;
        } else if (ls < 0 || ls >= DriverStrategy.values().length) {
            throw new CorruptConfigurationException(
                    "Illegal driver strategy in configuration: " + ls);
        } else {
            return DriverStrategy.values()[ls];
        }
    }

public <T1, T2> TypePairComparatorFactory<T1, T2> getPairComparatorFactory(ClassLoader cl) {
        final String className = this.config.getString(DRIVER_PAIR_COMPARATOR_FACTORY, null);
        if (className == null) {
            return null;
        }

        @SuppressWarnings("unchecked")
        final Class<TypePairComparatorFactory<T1, T2>> superClass =
                (Class<TypePairComparatorFactory<T1, T2>>)
                        (Class<?>) TypePairComparatorFactory.class;
        try {
            final Class<? extends TypePairComparatorFactory<T1, T2>> clazz =
                    Class.forName(className, true, cl).asSubclass(superClass);
            return InstantiationUtil.instantiate(clazz, superClass);
        } catch (ClassNotFoundException cnfex) {
            throw new RuntimeException(
                    "The class '"
                            + className
                            + "', noted in the configuration as "
                            + "pair comparator factory, could not be found. It is not part of the user code's class loader resources.");
        } catch (ClassCastException ccex) {
            throw new CorruptConfigurationException(
                    "The class noted in the configuration as the pair comparator factory "
                            + "is no subclass of TypePairComparatorFactory.");
        }
    }

public double getRelativeMemoryDriver() {
        return this.config.get(getDoubleConfigOption(MEMORY_DRIVER), 0.0);
    }

public CountingMutableObjectIterator(MutableObjectIterator<IN> iterator, Counter numRecordsIn) {
        this.iterator = iterator;
        this.numRecordsIn = numRecordsIn;
