public class InflightDataRescalingDescriptor implements Serializable {

    private static final int[] EMPTY_INT_ARRAY = new int[0];

    public static final InflightDataRescalingDescriptor NO_RESCALE = new NoRescalingDescriptor();

    private static final long serialVersionUID = -3396674344669796295L;

    /** Set when several operator instances are merged into one. */
    private final InflightDataGateOrPartitionRescalingDescriptor[] gateOrPartitionDescriptors;

    public InflightDataRescalingDescriptor(
            InflightDataGateOrPartitionRescalingDescriptor[] gateOrPartitionDescriptors) {
        this.gateOrPartitionDescriptors = checkNotNull(gateOrPartitionDescriptors);
    }

    public int[] getOldSubtaskIndexes(int gateOrPartitionIndex) {
        return gateOrPartitionDescriptors[gateOrPartitionIndex].getOldSubtaskInstances();
    }

    public RescaleMappings getChannelMapping(int gateOrPartitionIndex) {
        return gateOrPartitionDescriptors[gateOrPartitionIndex].getRescaleMappings();
    }

    public boolean isAmbiguous(int gateOrPartitionIndex, int oldSubtaskIndex) {
        return gateOrPartitionDescriptors[gateOrPartitionIndex].ambiguousSubtaskIndexes.contains(
                oldSubtaskIndex);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        InflightDataRescalingDescriptor that = (InflightDataRescalingDescriptor) o;
        return Arrays.equals(gateOrPartitionDescriptors, that.gateOrPartitionDescriptors);
    }

    @Override
    public int hashCode() {
        return Arrays.hashCode(gateOrPartitionDescriptors);
    }

    @Override
    public String toString() {
        return "InflightDataRescalingDescriptor{"
                + "gateOrPartitionDescriptors="
                + Arrays.toString(gateOrPartitionDescriptors)
                + '}';
    }

    /**
     * Captures ambiguous mappings of old channels to new channels.
     *
     * <p>For inputs, this mapping implies the following:
     * <li>
     *
     *     <ul>
     *       {@link #oldSubtaskIndexes} is set when there is a rescale on this task potentially
     *       leading to different key groups. Upstream task has a corresponding {@link
     *       #rescaledChannelsMappings} where it sends data over virtual channel while specifying
     *       the channel index in the VirtualChannelSelector. This subtask then demultiplexes over
     *       the virtual subtask index.
     * </ul>
     *
     * <ul>
     *   {@link #rescaledChannelsMappings} is set when there is a downscale of the upstream task.
     *   Upstream task has a corresponding {@link #oldSubtaskIndexes} where it sends data over
     *   virtual channel while specifying the subtask index in the VirtualChannelSelector. This
     *   subtask then demultiplexes over channel indexes.
     * </ul>
     *
     * <p>For outputs, it's vice-versa. The information must be kept in sync but they are used in
     * opposite ways for multiplexing/demultiplexing.
     *
     * <p>Note that in the common rescaling case both information is set and need to be
     * simultaneously used. If the input subtask subsumes the state of 3 old subtasks and a channel
     * corresponds to 2 old channels, then there are 6 virtual channels to be demultiplexed.
     */
    public static class InflightDataGateOrPartitionRescalingDescriptor implements Serializable {

        public static final InflightDataGateOrPartitionRescalingDescriptor NO_STATE =
                new InflightDataGateOrPartitionRescalingDescriptor(
                        EMPTY_INT_ARRAY,
                        RescaleMappings.SYMMETRIC_IDENTITY,
                        Collections.emptySet(),
                        MappingType.IDENTITY) {

                    private static final long serialVersionUID = 1L;

                    @Override
                    public int[] getOldSubtaskInstances() {
                        return EMPTY_INT_ARRAY;
                    }

                    @Override
                    public RescaleMappings getRescaleMappings() {
                        return RescaleMappings.SYMMETRIC_IDENTITY;
                    }
                };

        private static final long serialVersionUID = 1L;

        /** Set when several operator instances are merged into one. */
        private final int[] oldSubtaskIndexes;

        /**
         * Set when channels are merged because the connected operator has been rescaled for each
         * gate/partition.
         */
        private final RescaleMappings rescaledChannelsMappings;

        /** All channels where upstream duplicates data (only valid for downstream mappings). */
        private final Set<Integer> ambiguousSubtaskIndexes;

        private final MappingType mappingType;

        /** Type of mapping which should be used for this in-flight data. */
        public enum MappingType {
            IDENTITY,
            RESCALING
        }

        public InflightDataGateOrPartitionRescalingDescriptor(
                int[] oldSubtaskIndexes,
                RescaleMappings rescaledChannelsMappings,
                Set<Integer> ambiguousSubtaskIndexes,
                MappingType mappingType) {
            this.oldSubtaskIndexes = oldSubtaskIndexes;
            this.rescaledChannelsMappings = rescaledChannelsMappings;
            this.ambiguousSubtaskIndexes = ambiguousSubtaskIndexes;
            this.mappingType = mappingType;
        }

        public int[] getOldSubtaskInstances() {
            return oldSubtaskIndexes;
        }

        public RescaleMappings getRescaleMappings() {
            return rescaledChannelsMappings;
        }

        public boolean isIdentity() {
            return mappingType == MappingType.IDENTITY;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }
            InflightDataGateOrPartitionRescalingDescriptor that =
                    (InflightDataGateOrPartitionRescalingDescriptor) o;
            return Arrays.equals(oldSubtaskIndexes, that.oldSubtaskIndexes)
                    && Objects.equals(rescaledChannelsMappings, that.rescaledChannelsMappings)
                    && Objects.equals(ambiguousSubtaskIndexes, that.ambiguousSubtaskIndexes)
                    && mappingType == that.mappingType;
        }

        @Override
        public int hashCode() {
            int result =
                    Objects.hash(rescaledChannelsMappings, ambiguousSubtaskIndexes, mappingType);
            result = 31 * result + Arrays.hashCode(oldSubtaskIndexes);
            return result;
        }

        @Override
        public String toString() {
            return "InflightDataGateOrPartitionRescalingDescriptor{"
                    + "oldSubtaskIndexes="
                    + Arrays.toString(oldSubtaskIndexes)
                    + ", rescaledChannelsMappings="
                    + rescaledChannelsMappings
                    + ", ambiguousSubtaskIndexes="
                    + ambiguousSubtaskIndexes
                    + ", mappingType="
                    + mappingType
                    + '}';
        }
    }

    private static class NoRescalingDescriptor extends InflightDataRescalingDescriptor {
        private static final long serialVersionUID = 1L;

        public NoRescalingDescriptor() {
            super(new InflightDataGateOrPartitionRescalingDescriptor[0]);
        }

        @Override
        public int[] getOldSubtaskIndexes(int gateOrPartitionIndex) {
            return EMPTY_INT_ARRAY;
        }

        @Override
        public RescaleMappings getChannelMapping(int gateOrPartitionIndex) {
            return RescaleMappings.SYMMETRIC_IDENTITY;
        }

        @Override
        public boolean isAmbiguous(int gateOrPartitionIndex, int oldSubtaskIndex) {
            return false;
        }

        private Object readResolve() throws ObjectStreamException {
            return NO_RESCALE;
        }
    }
}

public class MemoryManager {

    private static final Logger LOG = LoggerFactory.getLogger(MemoryManager.class);

    /** The default memory page size. Currently set to 32 KiBytes. */
    public static final int DEFAULT_PAGE_SIZE = 32 * 1024;

    /** The minimal memory page size. Currently set to 4 KiBytes. */
    public static final int MIN_PAGE_SIZE = 4 * 1024;

    // ------------------------------------------------------------------------

    /** Memory segments allocated per memory owner. */
    private final Map<Object, Set<MemorySegment>> allocatedSegments;

    /** Reserved memory per memory owner. */
    private final Map<Object, Long> reservedMemory;

    private final long pageSize;

    private final long totalNumberOfPages;

    private final UnsafeMemoryBudget memoryBudget;

    private final SharedResources sharedResources;

    /** Flag whether the close() has already been invoked. */
    private volatile boolean isShutDown;

    /**
     * Creates a memory manager with the given capacity and given page size.
     *
     * @param memorySize The total size of the off-heap memory to be managed by this memory manager.
     * @param pageSize The size of the pages handed out by the memory manager.
     */
    MemoryManager(long memorySize, int pageSize) {
        sanityCheck(memorySize, pageSize);

        this.pageSize = pageSize;
        this.memoryBudget = new UnsafeMemoryBudget(memorySize);
        this.totalNumberOfPages = memorySize / pageSize;
        this.allocatedSegments = new ConcurrentHashMap<>();
        this.reservedMemory = new ConcurrentHashMap<>();
        this.sharedResources = new SharedResources();
        verifyIntTotalNumberOfPages(memorySize, totalNumberOfPages);

        LOG.debug(
                "Initialized MemoryManager with total memory size {} and page size {}.",
                memorySize,
                pageSize);
    }

    private static void sanityCheck(long memorySize, int pageSize) {
        Preconditions.checkArgument(memorySize >= 0L, "Size of total memory must be non-negative.");
        Preconditions.checkArgument(
                pageSize >= MIN_PAGE_SIZE,
                "The page size must be at least %d bytes.",
                MIN_PAGE_SIZE);
        Preconditions.checkArgument(
                MathUtils.isPowerOf2(pageSize), "The given page size is not a power of two.");
    }

    private static void verifyIntTotalNumberOfPages(long memorySize, long numberOfPagesLong) {
        Preconditions.checkArgument(
                numberOfPagesLong <= Integer.MAX_VALUE,
                "The given number of memory bytes (%d) corresponds to more than MAX_INT pages (%d > %d).",
                memorySize,
                numberOfPagesLong,
                Integer.MAX_VALUE);
    }

    // ------------------------------------------------------------------------
    //  Shutdown
    // ------------------------------------------------------------------------

    /**
     * Shuts the memory manager down, trying to release all the memory it managed. Depending on
     * implementation details, the memory does not necessarily become reclaimable by the garbage
     * collector, because there might still be references to allocated segments in the code that
     * allocated them from the memory manager.
     */
    public void shutdown() {
        if (!isShutDown) {
            // mark as shutdown and release memory
            isShutDown = true;
            reservedMemory.clear();

            // go over all allocated segments and release them
            for (Set<MemorySegment> segments : allocatedSegments.values()) {
                for (MemorySegment seg : segments) {
                    seg.free();
                }
                segments.clear();
            }
            allocatedSegments.clear();
        }
    }

    /**
     * Checks whether the MemoryManager has been shut down.
     *
     * @return True, if the memory manager is shut down, false otherwise.
     */
    @VisibleForTesting
    public boolean isShutdown() {
        return isShutDown;
    }

    /**
     * Checks if the memory manager's memory is completely available (nothing allocated at the
     * moment).
     *
     * @return True, if the memory manager is empty and valid, false if it is not empty or
     *     corrupted.
     */
    public boolean verifyEmpty() {
        return memoryBudget.verifyEmpty();
    }

    // ------------------------------------------------------------------------
    //  Memory allocation and release
    // ------------------------------------------------------------------------

    /**
     * Allocates a set of memory segments from this memory manager.
     *
     * <p>The total allocated memory will not exceed its size limit, announced in the constructor.
     *
     * @param owner The owner to associate with the memory segment, for the fallback release.
     * @param numPages The number of pages to allocate.
     * @return A list with the memory segments.
     * @throws MemoryAllocationException Thrown, if this memory manager does not have the requested
     *     amount of memory pages any more.
     */
    public List<MemorySegment> allocatePages(Object owner, int numPages)
            throws MemoryAllocationException {
        List<MemorySegment> segments = new ArrayList<>(numPages);
        allocatePages(owner, segments, numPages);
        return segments;
    }

    /**
     * Allocates a set of memory segments from this memory manager.
     *
     * <p>The total allocated memory will not exceed its size limit, announced in the constructor.
     *
     * @param owner The owner to associate with the memory segment, for the fallback release.
     * @param target The list into which to put the allocated memory pages.
     * @param numberOfPages The number of pages to allocate.
     * @throws MemoryAllocationException Thrown, if this memory manager does not have the requested
     *     amount of memory pages any more.
     */
    public void allocatePages(Object owner, Collection<MemorySegment> target, int numberOfPages)
            throws MemoryAllocationException {
        // sanity check
        Preconditions.checkNotNull(owner, "The memory owner must not be null.");
        Preconditions.checkState(!isShutDown, "Memory manager has been shut down.");
        Preconditions.checkArgument(
                numberOfPages <= totalNumberOfPages,
                "Cannot allocate more segments %s than the max number %s",
                numberOfPages,
                totalNumberOfPages);

        // reserve array space, if applicable
        if (target instanceof ArrayList) {
            ((ArrayList<MemorySegment>) target).ensureCapacity(numberOfPages);
        }

        long memoryToReserve = numberOfPages * pageSize;
        try {
            memoryBudget.reserveMemory(memoryToReserve);
        } catch (MemoryReservationException e) {
            throw new MemoryAllocationException(
                    String.format("Could not allocate %d pages", numberOfPages), e);
        }

        Runnable pageCleanup = this::releasePage;
        allocatedSegments.compute(
                owner,
                (o, currentSegmentsForOwner) -> {
                    Set<MemorySegment> segmentsForOwner =
                            currentSegmentsForOwner == null
                                    ? CollectionUtil.newHashSetWithExpectedSize(numberOfPages)
                                    : currentSegmentsForOwner;
                    for (long i = numberOfPages; i > 0; i--) {
                        MemorySegment segment =
                                allocateOffHeapUnsafeMemory(getPageSize(), owner, pageCleanup);
                        target.add(segment);
                        segmentsForOwner.add(segment);
                    }
                    return segmentsForOwner;
                });

        Preconditions.checkState(!isShutDown, "Memory manager has been concurrently shut down.");
    }

    private void releasePage() {
        memoryBudget.releaseMemory(getPageSize());
    }

    /**
     * Tries to release the memory for the specified segment.
     *
     * <p>If the segment has already been released, it is only freed. If it is null or has no owner,
     * the request is simply ignored. The segment is only freed and made eligible for reclamation by
