public SimpleFieldAccessor(TypeInformation<T> typeInfo) {
            checkNotNull(typeInfo, "typeInfo must not be null.");

            this.fieldType = typeInfo;
        }

public ArrayFieldAccessor(int pos, TypeInformation typeInfo) {
            if (pos < 0) {
                throw new CompositeType.InvalidFieldReferenceException(
                        "The "
                                + ((Integer) pos).toString()
                                + ". field selected on"
                                + " an array, which is an invalid index.");
            }
            checkNotNull(typeInfo, "typeInfo must not be null.");

            this.pos = pos;
            this.fieldType = BasicTypeInfo.getInfoFor(typeInfo.getTypeClass().getComponentType());
        }

SimpleTupleFieldAccessor(int pos, TypeInformation<T> typeInfo) {
            checkNotNull(typeInfo, "typeInfo must not be null.");
            int arity = ((TupleTypeInfo) typeInfo).getArity();
            if (pos < 0 || pos >= arity) {
                throw new CompositeType.InvalidFieldReferenceException(
                        "Tried to select "
                                + ((Integer) pos).toString()
                                + ". field on \""
                                + typeInfo.toString()
                                + "\", which is an invalid index.");
            }

            this.pos = pos;
            this.fieldType = ((TupleTypeInfo) typeInfo).getTypeAt(pos);
        }

RecursiveTupleFieldAccessor(
                int pos, FieldAccessor<R, F> innerAccessor, TypeInformation<T> typeInfo) {
            checkNotNull(typeInfo, "typeInfo must not be null.");
            checkNotNull(innerAccessor, "innerAccessor must not be null.");

            int arity = ((TupleTypeInfo) typeInfo).getArity();
            if (pos < 0 || pos >= arity) {
                throw new CompositeType.InvalidFieldReferenceException(
                        "Tried to select "
                                + ((Integer) pos).toString()
                                + ". field on \""
                                + typeInfo.toString()
                                + "\", which is an invalid index.");
            }

            this.pos = pos;
            this.innerAccessor = innerAccessor;
            this.fieldType = innerAccessor.fieldType;
        }

PojoFieldAccessor(Field field, FieldAccessor<R, F> innerAccessor) {
            checkNotNull(field, "field must not be null.");
            checkNotNull(innerAccessor, "innerAccessor must not be null.");

            this.field = field;
            this.innerAccessor = innerAccessor;
            this.fieldType = innerAccessor.fieldType;
        }

private static FieldExpression decomposeFieldExpression(String fieldExpression) {
        Matcher matcher = PATTERN_NESTED_FIELDS_WILDCARD.matcher(fieldExpression);
        if (!matcher.matches()) {
            throw new CompositeType.InvalidFieldReferenceException(
                    "Invalid field expression \"" + fieldExpression + "\".");
        }

        String head = matcher.group(0);
        if (head.equals(Keys.ExpressionKeys.SELECT_ALL_CHAR)
                || head.equals(Keys.ExpressionKeys.SELECT_ALL_CHAR_SCALA)) {
            throw new CompositeType.InvalidFieldReferenceException(
                    "No wildcards are allowed here.");
        } else {
            head = matcher.group(1);
        }

        String tail = matcher.group(3);

        return new FieldExpression(head, tail);
    }

/** Returns a product {@link FieldAccessor} that does not support recursion. */
<T, F> FieldAccessor<T, F> createSimpleProductFieldAccessor(
            int pos, TypeInformation<T> typeInfo, ExecutionConfig config);

/** Returns a product {@link FieldAccessor} that does support recursion. */
<T, R, F> FieldAccessor<T, F> createRecursiveProductFieldAccessor(
            int pos,
            TypeInformation<T> typeInfo,
            FieldAccessor<R, F> innerAccessor,
            ExecutionConfig config);

