        SqlIdentifier alias = call.getAlias();
        if (alias != null) {
            sourceTable = SqlValidatorUtil.addAlias(sourceTable, alias.getSimple());
        }
        return new SqlSelect(
                SqlParserPos.ZERO,
                null,
