/**
     * Checks whether the specified aggregate is the specified kind of Python function Aggregate.
     *
     * @param call the AggregateCall to check
     * @param pythonFunctionKind the kind of the python function
     * @return true if the specified call is a Python function Aggregate.
     */
public static boolean isPythonAggregate(
            AggregateCall call, PythonFunctionKind pythonFunctionKind) {
        SqlAggFunction aggregation = call.getAggregation();
        if (aggregation instanceof AggSqlFunction) {
            return isPythonFunction(
                    ((AggSqlFunction) aggregation).aggregateFunction(), pythonFunctionKind);
        } else if (aggregation instanceof BridgingSqlAggFunction) {
            return isPythonFunction(
                    ((BridgingSqlAggFunction) aggregation).getDefinition(), pythonFunctionKind);
        } else {
            return false;
        }
    }

/**
     * Similar to {@link TableConfig#getLocalTimeZone()} but extracting it from a generic {@link
     * ReadableConfig}.
     *
     * @see TableConfig#getLocalTimeZone()
     */
public static ZoneId getLocalTimeZone(ReadableConfig tableConfig) {
        final String zone = tableConfig.get(TableConfigOptions.LOCAL_TIME_ZONE);
        if (TableConfigOptions.LOCAL_TIME_ZONE.defaultValue().equals(zone)) {
            return ZoneId.systemDefault();
        }
        validateTimeZone(zone);
        return ZoneId.of(zone);
    }

/**
     * Get the shifted timezone of window if the time attribute type is TIMESTAMP_LTZ, always
     * returns UTC timezone if the time attribute type is TIMESTAMP which means do not shift.
     */
public static ZoneId getShiftTimeZone(LogicalType timeAttributeType, ZoneId zoneFromConfig) {
        boolean needShiftTimeZone = timeAttributeType instanceof LocalZonedTimestampType;
        return needShiftTimeZone ? zoneFromConfig : UTC_ZONE_ID;
    }

